/* Authored browser guidance. Keep crawlable English, all destination links and
 * the existing language owner; no network, AI, matching or account side effects. */
(function () {
  'use strict';
  if (window.top !== window || window.MatchAppFx || /MatchApp(?:TV|Ai(?:Kids)?)Android\/|\bwv\b/i.test(navigator.userAgent)) return;
  // Home title, matching explanation, free access, separation, Explore title,
  // Explore explanation, sources, reading guide invitation.
  var copy = {
    en: ['How Home works','Choose a mood, format, platform and era to get one entertainment match, a synopsis and official viewing options when verified for your country.','Guests have a small daily AI allowance. A free account increases it and lets you save your history. No credit card is needed to try it.','Kids Mode, account and support pages stay separate. MatchApp Ai helps you discover titles; it does not host streams.','Your guide to Explore','Home finds one audiovisual match. Explore opens books, cooking, news, events, music and Ask AI. All linked pages can be opened without an account.','Reading includes e-books, audiobooks and magazines with legal storefront links. News sends you to the original publisher; events link to official programmes. Music uses official videos and charts. Ask AI shares the daily allowance with Matches.','Explore the related destinations and practical guides below.'],
    pt: ['Como usar o início','Escolha humor, formato, plataforma e época para receber uma recomendação, uma sinopse e opções oficiais para assistir quando verificadas para seu país.','Visitantes têm uma pequena franquia diária de IA. Uma conta gratuita aumenta esse limite e permite salvar o histórico. Não é necessário cartão para experimentar.','Modo Kids, conta e suporte ficam separados. O MatchApp Ai ajuda a descobrir títulos; não hospeda transmissões.','Seu guia para explorar','O início encontra uma recomendação audiovisual. Explore reúne livros, culinária, notícias, eventos, música e Pergunte à IA. Todas as páginas vinculadas podem ser abertas sem conta.','A leitura inclui e-books, audiolivros e revistas com lojas legais. Notícias levam ao veículo original; eventos apontam para programas oficiais. Música usa vídeos oficiais e paradas. Pergunte à IA compartilha a franquia diária com Matches.','Confira os destinos relacionados e os guias práticos abaixo.'],
    es: ['Cómo usar el inicio','Elige ánimo, formato, plataforma y época para recibir una recomendación, sinopsis y opciones oficiales para verla cuando estén verificadas para tu país.','Los visitantes tienen un pequeño cupo diario de IA. Una cuenta gratuita lo amplía y permite guardar el historial. No necesitas tarjeta para probarlo.','El modo infantil, la cuenta y la ayuda permanecen separados. MatchApp Ai ayuda a descubrir títulos; no aloja emisiones.','Tu guía para explorar','Inicio encuentra una recomendación audiovisual. Explorar reúne libros, cocina, noticias, eventos, música y consultas a la IA. Puedes abrir todas las páginas enlazadas sin una cuenta.','La lectura incluye libros electrónicos, audiolibros y revistas con tiendas legales. Las noticias llevan al medio original y los eventos a programas oficiales. Música utiliza vídeos oficiales y listas. Consultar la IA comparte el cupo diario con Matches.','Consulta los destinos relacionados y las guías prácticas de abajo.'],
    fr: ['Comment utiliser l’accueil','Choisissez une humeur, un format, une plateforme et une époque pour obtenir une suggestion, un résumé et des options officielles de visionnage vérifiées pour votre pays.','Les visiteurs disposent d’un petit quota quotidien d’IA. Un compte gratuit augmente ce quota et permet de conserver l’historique. Aucune carte bancaire n’est nécessaire pour essayer.','Le mode enfants, le compte et l’assistance restent séparés. MatchApp Ai aide à découvrir des titres sans héberger de diffusion.','Votre guide pour explorer','L’accueil trouve une suggestion audiovisuelle. Explorer réunit livres, cuisine, actualités, événements, musique et questions à l’IA. Toutes les pages liées sont accessibles sans compte.','La lecture comprend livres numériques, livres audio et magazines avec des boutiques légales. Les actualités renvoient à l’éditeur original et les événements aux programmes officiels. Musique utilise vidéos officielles et classements. Les questions à l’IA partagent le quota quotidien de Matches.','Découvrez les destinations associées et les guides pratiques ci-dessous.'],
    de: ['So funktioniert die Startseite','Wähle Stimmung, Format, Plattform und Epoche für eine Empfehlung, eine Inhaltsangabe und offizielle Wiedergabeoptionen, soweit sie für dein Land bestätigt sind.','Gäste haben ein kleines tägliches KI-Kontingent. Ein kostenloses Konto erhöht es und speichert den Verlauf. Zum Ausprobieren ist keine Kreditkarte nötig.','Kindermodus, Konto und Hilfe bleiben getrennt. MatchApp Ai hilft bei der Titelsuche und stellt keine Streams bereit.','Dein Wegweiser zum Entdecken','Die Startseite findet eine audiovisuelle Empfehlung. Entdecken bietet Bücher, Kochen, Nachrichten, Veranstaltungen, Musik und KI-Fragen. Alle verlinkten Seiten lassen sich ohne Konto öffnen.','Lesen umfasst E-Books, Hörbücher und Magazine mit legalen Shops. Nachrichten verlinken zum Originalverlag, Veranstaltungen zu offiziellen Programmen. Musik nutzt offizielle Videos und Charts. KI-Fragen teilen das Tageskontingent mit Matches.','Entdecke die verknüpften Angebote und praktischen Ratgeber unten.'],
    it: ['Come usare la home','Scegli umore, formato, piattaforma ed epoca per ricevere un consiglio, una sinossi e opzioni ufficiali di visione quando verificate per il tuo paese.','Gli ospiti hanno una piccola quota giornaliera di IA. Un account gratuito la aumenta e permette di salvare la cronologia. Non serve una carta per provare.','Modalità bambini, account e assistenza restano separati. MatchApp Ai aiuta a scoprire titoli e non ospita streaming.','La tua guida per esplorare','La home trova un consiglio audiovisivo. Esplora riunisce libri, cucina, notizie, eventi, musica e domande all’IA. Tutte le pagine collegate si aprono senza account.','La lettura include e-book, audiolibri e riviste con negozi legali. Le notizie rimandano all’editore originale e gli eventi ai programmi ufficiali. Musica usa video ufficiali e classifiche. Le domande all’IA condividono la quota giornaliera con Matches.','Scopri le destinazioni correlate e le guide pratiche qui sotto.'],
    tr: ['Ana sayfa nasıl kullanılır','Ruh hali, biçim, platform ve dönem seçerek bir öneri, özet ve ülkeniz için doğrulanabildiğinde resmî izleme seçenekleri alın.','Misafirlerin günlük küçük bir yapay zekâ hakkı vardır. Ücretsiz hesap bu hakkı artırır ve geçmişi kaydeder. Denemek için kredi kartı gerekmez.','Çocuk modu, hesap ve destek ayrı kalır. MatchApp Ai içerik keşfetmenize yardımcı olur; yayın barındırmaz.','Keşif rehberiniz','Ana sayfa bir görsel-işitsel öneri bulur. Keşfet; kitapları, yemekleri, haberleri, etkinlikleri, müziği ve yapay zekâ sorularını bir araya getirir. Bağlantılı tüm sayfalar hesapsız açılır.','Okuma bölümü yasal mağaza bağlantılarıyla e-kitap, sesli kitap ve dergi içerir. Haberler asıl yayıncıya, etkinlikler resmî programlara yönlendirir. Müzik resmî videolar ve listeler kullanır. Yapay zekâ soruları Matches ile günlük hakkı paylaşır.','İlgili bölümleri ve aşağıdaki pratik rehberleri keşfedin.'],
    ru: ['Как пользоваться главной','Выберите настроение, формат, платформу и эпоху, чтобы получить рекомендацию, описание и официальные варианты просмотра, если они подтверждены для вашей страны.','Гостям доступен небольшой дневной лимит ИИ. Бесплатная учётная запись увеличивает его и позволяет сохранять историю. Для знакомства карта не нужна.','Детский режим, аккаунт и поддержка отделены. MatchApp Ai помогает находить произведения, но не размещает трансляции.','Ваш путеводитель','Главная подбирает одну аудиовизуальную рекомендацию. Здесь доступны книги, кулинария, новости, события, музыка и вопросы ИИ. Все связанные страницы можно открыть без аккаунта.','Раздел чтения включает электронные книги, аудиокниги и журналы со ссылками на легальные магазины. Новости ведут к первоисточнику, события — к официальным программам. Музыка использует официальные видео и чарты. Вопросы ИИ делят дневной лимит с Matches.','Откройте связанные разделы и практические руководства ниже.'],
    ar: ['كيفية استخدام الرئيسية','اختر المزاج والصيغة والمنصة والفترة للحصول على اقتراح واحد وملخص وخيارات مشاهدة رسمية عند التحقق منها لبلدك.','للزوار حصة يومية صغيرة من الذكاء الاصطناعي. يزيد الحساب المجاني هذه الحصة ويتيح حفظ السجل. لا تحتاج إلى بطاقة لتجربة الخدمة.','يبقى وضع الأطفال والحساب والدعم منفصلين. يساعد MatchApp Ai على اكتشاف الأعمال ولا يستضيف البث.','دليلك للاستكشاف','تجد الرئيسية اقتراحاً سمعياً بصرياً واحداً. يجمع الاستكشاف الكتب والطهي والأخبار والفعاليات والموسيقى وأسئلة الذكاء الاصطناعي. يمكن فتح كل الصفحات المرتبطة دون حساب.','تشمل القراءة الكتب الإلكترونية والصوتية والمجلات مع متاجر قانونية. تقود الأخبار إلى الناشر الأصلي والفعاليات إلى البرامج الرسمية. تستخدم الموسيقى فيديوهات رسمية وقوائم ترتيب. تشترك أسئلة الذكاء الاصطناعي مع Matches في الحصة اليومية.','استكشف الوجهات المرتبطة والأدلة العملية أدناه.'],
    hi: ['होम का उपयोग कैसे करें','मूड, प्रारूप, प्लेटफ़ॉर्म और दौर चुनकर एक सुझाव, सारांश और आपके देश के लिए सत्यापित होने पर आधिकारिक देखने के विकल्प पाएँ।','अतिथियों को रोज़ कुछ एआई अनुरोध मिलते हैं। मुफ़्त खाता यह सीमा बढ़ाता है और इतिहास सहेजने देता है। आज़माने के लिए कार्ड नहीं चाहिए।','बच्चों का मोड, खाता और सहायता अलग रहते हैं। MatchApp Ai सामग्री खोजने में मदद करता है; यह स्ट्रीम होस्ट नहीं करता।','आपकी खोज गाइड','होम एक ऑडियोविज़ुअल सुझाव देता है। यहाँ किताबें, खाना, समाचार, कार्यक्रम, संगीत और एआई प्रश्न मिलते हैं। जुड़े सभी पेज बिना खाते के खोले जा सकते हैं।','पढ़ने में कानूनी दुकानों के लिंक वाली ई-बुक, ऑडियोबुक और पत्रिकाएँ शामिल हैं। समाचार मूल प्रकाशक और कार्यक्रम आधिकारिक विवरण तक ले जाते हैं। संगीत में आधिकारिक वीडियो और चार्ट हैं। एआई प्रश्न और Matches एक ही दैनिक सीमा इस्तेमाल करते हैं।','नीचे संबंधित विकल्प और व्यावहारिक गाइड देखें।'],
    id: ['Cara memakai beranda','Pilih suasana hati, format, platform dan era untuk mendapat satu rekomendasi, sinopsis serta pilihan menonton resmi bila sudah diverifikasi untuk negara Anda.','Tamu mendapat sedikit kuota AI harian. Akun gratis menambah kuota dan menyimpan riwayat. Tidak perlu kartu untuk mencoba.','Mode anak, akun dan bantuan tetap terpisah. MatchApp Ai membantu menemukan judul dan tidak menghosting siaran.','Panduan menjelajah','Beranda menemukan satu rekomendasi audiovisual. Jelajahi menyatukan buku, memasak, berita, acara, musik dan pertanyaan AI. Semua halaman tertaut dapat dibuka tanpa akun.','Bacaan meliputi e-book, buku audio dan majalah dengan toko legal. Berita menuju penerbit asli dan acara menuju program resmi. Musik memakai video resmi dan tangga lagu. Pertanyaan AI berbagi kuota harian dengan Matches.','Lihat tujuan terkait dan panduan praktis di bawah.'],
    ja: ['ホームの使い方','気分、形式、配信サービス、年代を選ぶと、おすすめ1作品、あらすじ、お住まいの国で確認できた公式の視聴先が表示されます。','ゲストには少量の1日分のAI利用枠があります。無料アカウントで枠が増え、履歴も保存できます。試用にクレジットカードは不要です。','キッズモード、アカウント、サポートは別の画面です。MatchApp Aiは作品を探すガイドで、映像配信は行いません。','探索ガイド','ホームは映像作品を1つ提案します。探索では本、料理、ニュース、イベント、音楽、AIへの質問を利用できます。リンク先はすべてアカウントなしで開けます。','読書には電子書籍、オーディオブック、雑誌と正規販売店へのリンクがあります。ニュースは元の出版社、イベントは公式プログラムへ案内します。音楽は公式動画とチャートを使用します。AIへの質問はMatchesと1日の利用枠を共有します。','関連するページと実用ガイドを以下からご覧ください。'],
    ko: ['홈 사용 방법','기분, 형식, 플랫폼, 시대를 선택하면 추천 작품 하나와 줄거리, 해당 국가에서 확인된 공식 시청 경로를 볼 수 있습니다.','방문자에게는 소량의 일일 AI 이용 한도가 제공됩니다. 무료 계정은 한도를 늘리고 기록을 저장합니다. 체험에는 카드가 필요하지 않습니다.','키즈 모드, 계정, 고객 지원은 별도로 유지됩니다. MatchApp Ai는 작품 탐색을 돕고 스트리밍을 제공하지 않습니다.','탐색 안내','홈은 영상 작품 하나를 추천합니다. 탐색에서는 책, 요리, 뉴스, 행사, 음악, AI 질문을 이용할 수 있습니다. 연결된 모든 페이지는 계정 없이 열 수 있습니다.','독서에는 전자책, 오디오북, 잡지와 합법적인 판매처 링크가 있습니다. 뉴스는 원래 발행처로, 행사는 공식 프로그램으로 연결됩니다. 음악은 공식 영상과 차트를 사용합니다. AI 질문은 Matches와 일일 이용 한도를 공유합니다.','아래의 관련 페이지와 실용적인 안내를 확인하세요.'],
    zh: ['首页使用指南','选择心情、形式、平台和年代，即可获得一部推荐作品、简介，以及经核实适用于所在国家的官方观看渠道。','访客每天有少量AI使用额度。免费账户可提高额度并保存历史记录。试用无需信用卡。','儿童模式、账户和支持页面保持独立。MatchApp Ai帮助发现作品，不提供流媒体播放服务。','探索指南','首页推荐一部视听作品。探索汇集图书、烹饪、新闻、活动、音乐和AI问答。所有链接页面无需账户即可打开。','阅读涵盖电子书、有声书和杂志，并提供合法商店链接。新闻链接到原始出版方，活动链接到官方节目。音乐使用官方视频和排行榜。AI问答与Matches共享每日额度。','请查看下方相关页面和实用指南。'],
    'zh-TW': ['首頁使用指南','選擇心情、形式、平台和年代，即可獲得一部推薦作品、簡介，以及經查證適用於所在國家的官方觀看管道。','訪客每天有少量AI使用額度。免費帳戶可提高額度並儲存歷史紀錄。試用無需信用卡。','兒童模式、帳戶和支援頁面保持獨立。MatchApp Ai協助探索作品，不提供串流播放服務。','探索指南','首頁推薦一部視聽作品。探索匯集書籍、烹飪、新聞、活動、音樂和AI問答。所有連結頁面無需帳戶即可開啟。','閱讀涵蓋電子書、有聲書和雜誌，並提供合法商店連結。新聞連結至原始出版者，活動連結至官方節目。音樂使用官方影片和排行榜。AI問答與Matches共享每日額度。','請查看下方相關頁面和實用指南。']
  };
  var guideNames={en:['How MatchApp Ai works','Choosing what to watch','Choosing together'],pt:['Como o MatchApp Ai funciona','Como escolher o que assistir','Como escolher juntos'],es:['Cómo funciona MatchApp Ai','Cómo elegir qué ver','Cómo elegir juntos'],fr:['Comment fonctionne MatchApp Ai','Choisir quoi regarder','Choisir ensemble'],de:['So funktioniert MatchApp Ai','Was soll ich ansehen?','Gemeinsam auswählen'],it:['Come funziona MatchApp Ai','Scegliere cosa guardare','Scegliere insieme'],tr:['MatchApp Ai nasıl çalışır','Ne izleyeceğinizi seçin','Birlikte seçim yapın'],ru:['Как работает MatchApp Ai','Как выбрать, что смотреть','Как выбирать вместе'],ar:['كيف يعمل MatchApp Ai','اختيار ما تشاهده','الاختيار معاً'],hi:['MatchApp Ai कैसे काम करता है','क्या देखें, कैसे चुनें','मिलकर कैसे चुनें'],id:['Cara kerja MatchApp Ai','Memilih tontonan','Memilih bersama'],ja:['MatchApp Aiの使い方','見る作品の選び方','一緒に選ぶ方法'],ko:['MatchApp Ai 사용법','볼 작품 고르기','함께 고르기'],zh:['MatchApp Ai使用说明','如何选择观看作品','一起选择作品'],'zh-TW':['MatchApp Ai使用說明','如何選擇觀看作品','一起選擇作品']};
  var guidePaths=['/how-it-works.html','/guides/choose-what-to-watch/','/guides/what-to-watch-when-you-disagree/'];
  var home=document.getElementById('ma-home-static-intro'), explore=document.querySelector('.ma-explore-static-guide');
  var originals=new Map();
  [home,explore].filter(Boolean).forEach(function(section){originals.set(section,section.innerHTML)});
  var lede=document.querySelector('.ma-explore-lede-extra');
  // Move the long explanation out of the narrow photographic hero. The full
  // original guide remains visible after the destination grids, also without JS.
  if(explore){
    if(lede)explore.insertBefore(lede,explore.children[1]||null);
    var more=document.querySelector('.ref-explore-more');if(more)more.after(explore);
    originals.set(explore,explore.innerHTML);
  }
  function chosen(){var raw=String(window.MATCH_LANG||document.documentElement.lang||'en');return /^zh-(TW|HK|Hant)/i.test(raw)?'zh-TW':raw.toLowerCase().split('-')[0]}
  function paint(){
    var lang=chosen(),row=copy[lang]||copy.en;
    [home,explore].filter(Boolean).forEach(function(section){
      if(section.dataset.guideLocale===lang)return;
      section.innerHTML=originals.get(section);section.dataset.guideLocale=lang;
      if(lang==='en')return;
      var heading=section.querySelector('h2');heading.textContent=row[section===home?0:4];
      var paras=Array.from(section.querySelectorAll('p'));
      // Preserve every original destination link; label them from the already
      // localized navigation/card when available, with an authored fallback.
      var links=Array.from(section.querySelectorAll('a')).map(function(a){
        var known=guidePaths.indexOf(a.getAttribute('href'));
        if(known!==-1){a.textContent=(guideNames[lang]||guideNames.en)[known];return a;}
        var found=Array.from(document.querySelectorAll('a[href]')).find(function(x){return !section.contains(x)&&x.getAttribute('href')===a.getAttribute('href')&&x.textContent.trim()});
        if(found)a.textContent=found.querySelector('h2,[data-ref-explore],[data-i18n]')?.textContent||found.textContent.trim();
        return a;
      });
      paras.forEach(function(p){p.remove()});
      var list=section.querySelector('ul');if(list)list.remove();
      (section===home?[row[1],row[2],row[3],row[7]]:[row[5],row[6],row[7]]).forEach(function(text){var p=document.createElement('p');p.textContent=text;section.appendChild(p)});
      var nav=document.createElement('nav');nav.className='ma-browser-guide-links';
      var seen=new Set();links.forEach(function(a){var href=a.getAttribute('href');if(!seen.has(href)){seen.add(href);nav.appendChild(a)}});section.appendChild(nav);
    });
  }
  paint();document.addEventListener('matchapp:langchange',paint);window.addEventListener('matchapp:languagechange',paint);
})();
